<script setup lang="ts">
import Button from 'primevue/button'; import {BrowserQRCodeReader} from '@zxing/browser'; import {onBeforeUnmount,ref} from 'vue'; import {useToast} from 'primevue/usetoast'; import AppPageHeader from '@/components/app/AppPageHeader.vue'; import {captureActionLabel,getTodayMarks,markCapture,resolveCapture} from '@/modules/attendance-capture/attendance-capture.service'; import type {CaptureAction,CaptureResolution,TodayMark} from '@/modules/attendance-capture/attendance-capture.types'; import {getUserFriendlyApiError} from '@/services/api-errors'
const toast=useToast(),video=ref<HTMLVideoElement|null>(null),scannerError=ref(''),scanning=ref(false),resolving=ref(false),marking=ref(false),token=ref(''),resolution=ref<CaptureResolution|null>(null),marks=ref<TodayMark[]>([]),reader=new BrowserQRCodeReader();let controls:{stop:()=>void}|undefined;
const isDevelopment=import.meta.env.DEV
const labels:Record<string,string>={Entry:'Entrada',LunchStart:'Inicio de almuerzo',LunchEnd:'Fin de almuerzo',Exit:'Salida',CommissionExit:'Salida a comisión',CommissionReturn:'Regreso de comisión',OtherExit:'Otra salida',OtherReturn:'Retorno'}
async function loadMarks(){try{marks.value=await getTodayMarks()}catch(e){scannerError.value=getUserFriendlyApiError(e)}}async function resolve(tokenValue:string){if(!tokenValue||resolving.value)return;resolving.value=true;scannerError.value='';try{token.value=tokenValue;resolution.value=await resolveCapture(tokenValue)}catch(e){resolution.value=null;scannerError.value=getUserFriendlyApiError(e)}finally{resolving.value=false}}async function startCamera(){scannerError.value='';if(!navigator.mediaDevices?.getUserMedia){scannerError.value='Tu navegador no permite usar la cámara.';return}try{scanning.value=true;controls=await reader.decodeFromVideoDevice(undefined,video.value!,result=>{if(result){controls?.stop();scanning.value=false;void resolve(result.getText())}})}catch(e){scanning.value=false;scannerError.value='No se pudo abrir la cámara. Revisa el permiso e inténtalo nuevamente.'}}function stopCamera(){controls?.stop();controls=undefined;scanning.value=false}async function confirm(action:CaptureAction){if(!token.value||marking.value)return;marking.value=true;try{const result=await markCapture(token.value,action);toast.add({severity:'success',summary:'Marcación registrada',detail:`${result.message} ${new Intl.DateTimeFormat('es-PE',{timeStyle:'short',timeZone:'America/Lima'}).format(new Date(result.occurredAt))}`,life:4000});resolution.value=null;token.value='';await loadMarks()}catch(e){scannerError.value=getUserFriendlyApiError(e)}finally{marking.value=false}}onBeforeUnmount(stopCamera);void loadMarks()
</script>
<template><section class="mark-view"><AppPageHeader title="Marcar asistencia" description="Escanea el código QR del checkpoint."/><article class="app-surface mark-camera"><video ref="video" autoplay playsinline aria-label="Vista de cámara para escanear código QR"></video><p v-if="!scanning">Usa la cámara para leer el QR dinámico del checkpoint.</p><Button :label="scanning?'Detener cámara':'Abrir cámara'" :icon="scanning?'pi pi-stop':'pi pi-camera'" @click="scanning?stopCamera():startCamera()"/></article><details v-if="isDevelopment" class="app-surface"><summary>Diagnóstico: pegar token QR</summary><form class="absence-form" @submit.prevent="resolve(token)"><input v-model="token" aria-label="Token QR de diagnóstico"/><Button label="Resolver token" type="submit" :loading="resolving"/></form></details><p v-if="scannerError" class="mark-error">{{scannerError}}</p><article v-if="resolution" class="app-surface mark-resolution"><h2>{{resolution.checkpoint.name}}</h2><p>{{resolution.message}}</p><div class="mark-actions"><Button v-for="action in resolution.availableActions" :key="action" :label="captureActionLabel(action)" :loading="marking" :disabled="marking" @click="confirm(action)"/></div></article><article class="app-surface"><h2 class="app-surface__title">Marcaciones de hoy</h2><p v-if="!marks.length">Aún no registras marcaciones hoy.</p><ul v-else class="mark-history"><li v-for="mark in marks" :key="mark.id"><strong>{{labels[mark.type]??mark.type}}</strong><span>{{new Intl.DateTimeFormat('es-PE',{timeStyle:'short',timeZone:'America/Lima'}).format(new Date(mark.occurredAt))}}</span><small v-if="mark.checkpoint">{{mark.checkpoint.name}}</small></li></ul></article></section></template>
